#include "extrusion_helper.hpp"
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("SHADERS VERTICES NEWOUT normal|no-depth");std::string mode=argv[4];if(mode!="normal"&&mode!="no-depth")throw std::runtime_error("mode");gBadDepth=mode=="no-depth";
 std::ifstream f(argv[2],std::ios::binary|std::ios::ate);if(!f||f.tellg()<=0||f.tellg()%72||f.tellg()>65536)throw std::runtime_error("vertex size");std::vector<float>v(size_t(f.tellg())/4);f.seekg(0);f.read((char*)v.data(),v.size()*4);for(size_t i=0;i<v.size();i+=6){for(int k=0;k<6;k++)if(!std::isfinite(v[i+k]))throw std::runtime_error("nonfinite");if(v[i]<0||v[i]>65||v[i+1]<0||v[i+1]>49||v[i+2]<0||v[i+2]>6)throw std::runtime_error("coordinate budget");for(int k=3;k<6;k++)if(v[i+k]<0||v[i+k]>1)throw std::runtime_error("color budget");}
 std::filesystem::path out=argv[3];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");{TextLab lab(argv[1]);lab.vertexBuffer=lab.buffers.size();lab.buffers.push_back(lab.buffer(v.size()*4,VK_BUFFER_USAGE_VERTEX_BUFFER_BIT));std::memcpy(lab.buffers[lab.vertexBuffer].map,v.data(),v.size()*4);lab.vertexCount=v.size()/6;auto result=lab.draw(std::vector<float>(65*49,1),{.1f,.2f,.3f,1},{1,1,1,1});save(out/"color.f32",result[0]);save(out/"velocity.f32",result[1]);save(out/"id.f32",result[2]);std::vector<float>d(65*49);std::memcpy(d.data(),lab.buffers[lab.readDepth].map,d.size()*4);save(out/"depth.f32",d);std::cout<<"EXTRUSION_PASS validation_enabled="<<lab.validation<<"\n";}if(validationErrors)throw std::runtime_error("validation");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
